try:
	ids = list(value['itemAssetRateIds'] or [])
except:
	ids = []
if not ids: return {'single': False, 'usesTooling': False}
rows = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.item.getAssetItems({'itemAssetRateIdList': ids, 'includeTooling': True}))
pairs = set((row['assetId'], row['itemId']) for row in rows)
if len(pairs) != 1: return {'single': False, 'usesTooling': False}
row = rows[0]
usesTooling = system.kanoa.utilities.getFieldValue('usesTooling', system.kanoa.asset.getAssets({'assetId': row['assetId']}))
tools = set(r['toolingAssetId'] for r in rows)
return {'single': True, 'usesTooling': bool(usesTooling), 'assetId': row['assetId'], 'itemId': row['itemId'],
		'assetPath': row['assetPath'], 'itemName': row['itemName'], 'tool': (list(tools)[0] or 0) if len(tools) == 1 else None}

ctx, info = value['ctx'], value['info']
if ctx['single']:
	text = '%s on %s' % (ctx['itemName'], system.kanoa.utilities.formatPath(ctx['assetPath'], {}))
	return text + (' (new rate)' if info['isNew'] else '')
return '%s rates: %s' % (len(info['itemAssetRateIds']), list(info['itemAssetRateIds']))
